//! The one-time load of the JSON ledgers into the database.
//!
//! Two populations, and they are NOT two versions of one thing. The COMMITTED store
//! (`graph/algorithms.json` + `graph/records/*.json`) is what the build compiles; the RUNTIME store
//! (`~/.base-studio-code/knowledge/algorithms.json`) is what the app reads and what a librarian
//! authors into. MEASURED 2026-09-08, by extension:
//!
//! | store | `.rs` | `.ts` | total |
//! |---|---|---|---|
//! | committed | 1729 | 79 | 1808 |
//! | runtime | 700 | 690 | 1406 |
//!
//! They OVERLAP on 602 ids and are otherwise complementary — the committed store is the Rust
//! authority, the runtime store carries the frontend records that ship in the packaged seed. A union
//! is therefore the wrong shape, and the first cut of this import took one anyway.
//!
//! # The COMMITTED body wins, because it is the only population known to compile
//!
//! For an id in both, the runtime body goes in first and the committed body second, so the committed
//! copy is head and the runtime one is exactly one [`crate::revert`] away. Nothing is discarded and
//! nothing is guessed; what is chosen is which side the BUILD sees.
//!
//! This is the reverse of the first cut, which took the runtime side on the stated grounds that it is
//! the authoring surface `bsc graph promote` already treats as authoritative. That is true of a record
//! a librarian edits in the app, and false of the store as a whole, in two directions that were
//! measured rather than argued:
//!
//! - **It misses `--repo` writes.** `bsc graph impl set --repo` writes the committed store directly and
//!   never touches the runtime one. This very module was at rev 3 in the runtime store — genuinely
//!   authored, newest timestamp of any record — and still missing two functions that were committed
//!   hours earlier. So neither `rev` nor `updatedAt` orders the two stores.
//! - **It misses whole waves.** Nine crate roots (`bsc-util--lib.rs`, `bsc-record--lib.rs`, …) sat in
//!   the runtime store frozen at their PRE-DECOMPOSITION bodies, created 2026-09-05 and never authored
//!   since. Taking those re-introduces a crate's entire body beside the children that now hold it.
//!
//! The failure was not subtle once it was looked at: `bsc-graph--lib.rs` lost its `ImportSpec`
//! re-export and the workspace stopped building with `error[E0432]`. The guard is
//! `export_of_main_reproduces_the_committed_store`, which asserts the property this rule exists to
//! hold rather than the rule itself.
//!
//! # Runtime-only ids land on a LANE, not on `main`
//!
//! 804 ids exist only in the runtime store, and they are not missing crate modules — 637 are frontend
//! records that live in the packaged seed, and 15 are crates from OTHER branches that the shared
//! runtime store happened to be holding (`bsc-rf`, `bsc-sentinel`). Putting those on `main` exports
//! them into this branch's `graph/records/`, which is the promote-sweep failure with extra steps.
//!
//! So they import onto [`RUNTIME_LANE`]: present, queryable, and landable one at a time with
//! [`crate::land`] — but not on `main`, so the export cannot write them into the repo. Adopting the
//! seed population into the repo store is its own migration, and it should be a decision somebody
//! makes rather than a side effect of this one.
//!
//! # Pre-migration history is PROVENANCE, not revisions
//!
//! The old format kept history inline and pruned content from all but the newest entry
//! (`bsc_record::prune_prev_src`): MEASURED, 405 of 2,313 entries carry `prevSrc` and the other 1,908
//! record only who/when/what-changed. Importing those as revision rows would create versions that
//! `revert` cannot restore — worse than not having them, because the store's whole promise is that a
//! version is somewhere you can go back to. So they land verbatim in [`LEGACY_HISTORY`], readable and
//! plainly labelled as from before the ledger, and rev 1 in the ledger is the first version this store
//! can actually stand behind.

use crate::{head_rev_in, put_in, Write, MAIN, TIER_EDGE, TIER_IMPL};
use rusqlite::{params, Connection};
use serde_json::Value;

/// The pre-migration `history` arrays, verbatim. Provenance only — see the module docs.
pub const LEGACY_HISTORY: &str = "legacy_history";

/// The lane runtime-only ids import onto, rather than `main`.
///
/// They are the packaged-seed frontend population plus whatever other branches' records the shared
/// runtime store was holding — reachable and landable, but never exported into `graph/records/`.
pub const RUNTIME_LANE: &str = "runtime-import";

/// The fields the LEDGER owns, stripped from a body on the way in.
///
/// `rev`/`updatedAt`/`updatedBy`/`history` were the record carrying its own bookkeeping because there
/// was nowhere else to put it. There is now: they are columns and rows. Leaving them in the body would
/// mean two answers to "what rev is this" that drift the moment anything writes.
const LEDGER_OWNED: &[&str] = &["rev", "updatedAt", "updatedBy", "history", "build"];

/// The extra schema the import needs, applied alongside [`crate::SCHEMA`].
pub const IMPORT_SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS legacy_history (
  id    TEXT    NOT NULL,
  seq   INTEGER NOT NULL,
  entry TEXT    NOT NULL,
  PRIMARY KEY (id, seq)
);
"#;

/// What one import did, or would do.
#[derive(Debug, Default, PartialEq, Eq, serde::Serialize)]
pub struct Report {
    /// Ids seen only in the committed store — the crate modules the app's library never had.
    pub committed_only: usize,
    /// Ids seen only in the runtime store — imported onto [`RUNTIME_LANE`], not `main`.
    pub runtime_only: usize,
    /// Ids in both with IDENTICAL content — one version is enough.
    pub agreed: usize,
    /// Ids in both that DISAGREE — imported as two versions, COMMITTED current.
    pub disagreed: usize,
    /// Records already in the ledger, left alone.
    pub skipped: usize,
    /// Legacy history entries preserved as provenance.
    pub legacy_entries: usize,
    /// Revision rows written.
    pub revs_written: usize,
    /// Flat records a `--mod.rs` decomposition had already replaced, tombstoned on the way in.
    pub superseded: usize,
}

/// A record body with the ledger's own fields removed.
pub fn body_of(rec: &Value) -> Value {
    let Some(obj) = rec.as_object() else { return rec.clone() };
    Value::Object(obj.iter().filter(|(k, _)| !LEDGER_OWNED.contains(&k.as_str())).map(|(k, v)| (k.clone(), v.clone())).collect())
}

/// Whether two bodies say the same thing, ignoring the ledger's fields and key order.
fn same(a: &Value, b: &Value) -> bool {
    // Through a canonical string rather than `==` on `Value`: `preserve_order` is on in this workspace,
    // so two records with identical content and different key order compare unequal, and every promoted
    // record would import as a spurious disagreement.
    fn canon(v: &Value) -> String {
        match v {
            Value::Object(m) => {
                let mut keys: Vec<&String> = m.keys().collect();
                keys.sort();
                let inner: Vec<String> = keys.iter().map(|k| format!("{k}:{}", canon(&m[*k]))).collect();
                format!("{{{}}}", inner.join(","))
            }
            Value::Array(a) => format!("[{}]", a.iter().map(canon).collect::<Vec<_>>().join(",")),
            other => other.to_string(),
        }
    }
    canon(a) == canon(b)
}

/// Load `committed` and `runtime` into `conn`.
///
/// Idempotent by id: a record already in the ledger is SKIPPED, never re-imported, so running this
/// twice does not double every history. `by` stamps the imported revisions.
pub fn import(
    conn: &Connection,
    committed: &[Value],
    runtime: &[Value],
    by: &str,
) -> Result<Report, String> {
    let mut rep = import_tier(conn, committed, runtime, by, TIER_IMPL)?;
    // A decomposition retires its predecessor in the COMMITTED store, and the runtime store never
    // hears about it — so the union carries both, which is two records claiming one module and a build
    // that refuses to start.
    rep.superseded = supersede_decomposed(conn, by)?.len();
    Ok(rep)
}

/// The RELATIONSHIP tier, on the same terms as [`import`].
///
/// Edges were the migration's silent hole: the committed monolith carries 8 and the runtime store 81,
/// and neither reached the ledger, so the first export wrote `"edges": []` over all of them. They are
/// records like any other — same precedence, same lane rule, same recoverability — they just live on
/// [`TIER_EDGE`], and nothing but the tier differs.
pub fn import_edges(
    conn: &Connection,
    committed: &[Value],
    runtime: &[Value],
    by: &str,
) -> Result<Report, String> {
    import_tier(conn, committed, runtime, by, TIER_EDGE)
}

/// The shared body of [`import`] and [`import_edges`].
fn import_tier(
    conn: &Connection,
    committed: &[Value],
    runtime: &[Value],
    by: &str,
    tier: &str,
) -> Result<Report, String> {
    let put = |lane: &str, id: &str, body: &Value, note: &str| -> Result<i64, String> {
        put_in(conn, lane, id, body, Write::by(by).note(Some(note)).tier(tier))
    };
    conn.execute_batch(IMPORT_SCHEMA).map_err(|e| format!("legacy history schema: {e}"))?;
    let key = |r: &Value| r.get("id").and_then(Value::as_str).unwrap_or_default().to_string();
    let mut rep = Report::default();

    let mut ids: Vec<String> = Vec::new();
    let mut c_by_id: std::collections::BTreeMap<String, &Value> = Default::default();
    let mut r_by_id: std::collections::BTreeMap<String, &Value> = Default::default();
    for r in committed {
        let k = key(r);
        if !k.is_empty() && c_by_id.insert(k.clone(), r).is_none() {
            ids.push(k);
        }
    }
    for r in runtime {
        let k = key(r);
        if k.is_empty() {
            continue;
        }
        if r_by_id.insert(k.clone(), r).is_none() && !c_by_id.contains_key(&k) {
            ids.push(k);
        }
    }

    for id in ids {
        // Idempotent across BOTH homes: a runtime-only id lands on `RUNTIME_LANE`, where a check
        // against `main` alone would see nothing and re-import it on every run.
        if head_rev_in(conn, MAIN, &id)? > 0 || head_rev_in(conn, RUNTIME_LANE, &id)? > 0 {
            rep.skipped += 1;
            continue;
        }
        let c = c_by_id.get(&id).map(|r| body_of(r));
        let r = r_by_id.get(&id).map(|r| body_of(r));

        // The legacy history rides on whichever side carries it — the runtime store, in practice.
        // Implementations only: an edge has no inline history to preserve.
        for src in [r_by_id.get(&id), c_by_id.get(&id)].into_iter().flatten().filter(|_| tier == TIER_IMPL) {
            if let Some(hist) = src.get("history").and_then(Value::as_array) {
                for (seq, entry) in hist.iter().enumerate() {
                    let text = serde_json::to_string(entry).map_err(|e| e.to_string())?;
                    conn.execute(
                        "INSERT OR IGNORE INTO legacy_history (id, seq, entry) VALUES (?1, ?2, ?3)",
                        params![id, seq as i64, text],
                    )
                    .map_err(|e| format!("legacy history for '{id}': {e}"))?;
                    rep.legacy_entries += 1;
                }
                break;
            }
        }

        match (c, r) {
            (Some(c), Some(r)) if same(&c, &r) => {
                // The COMMITTED body even here. `same` ignores key ORDER (it must — `preserve_order` is
                // on, and the two stores routinely order keys differently), so the two bodies agree on
                // content while serializing to different bytes. Taking the runtime one rewrote 16
                // records to no effect on every export.
                let _ = &r;
                put(MAIN, &id, &c, "imported (committed and runtime agreed)")?;
                rep.agreed += 1;
                rep.revs_written += 1;
            }
            (Some(c), Some(r)) => {
                // BOTH, and the COMMITTED body goes in LAST so it is head: it is the only one of the
                // two populations known to compile. The runtime body is one `revert` away rather than
                // a judgement call made once at import time. See the module docs for why neither
                // `rev` nor `updatedAt` can order these two stores.
                put(MAIN, &id, &r, "imported from the runtime store (differed)")?;
                put(MAIN, &id, &c, "imported from the committed store")?;
                rep.disagreed += 1;
                rep.revs_written += 2;
            }
            (Some(c), None) => {
                put(MAIN, &id, &c, "imported from the committed store")?;
                rep.committed_only += 1;
                rep.revs_written += 1;
            }
            (None, Some(r)) => {
                // NOT `main` — the repo store never had this id, and the export writes `main` into
                // `graph/records/`. On a lane it stays reachable and landable without the migration
                // silently adopting the seed population and other branches' records.
                put(RUNTIME_LANE, &id, &r, "imported from the runtime store (runtime-only)")?;
                rep.runtime_only += 1;
                rep.revs_written += 1;
            }
            (None, None) => {}
        }
    }
    // A decomposition retires its predecessor in the COMMITTED store, and the runtime store never
    // hears about it — so the union carries both, which is two records claiming one module and a build
    // that refuses to start.
    rep.superseded = supersede_decomposed(conn, by)?.len();
    Ok(rep)
}

/// The Rust MODULE PATH a record claims — `…/src/connector/mod.rs` and `…/src/connector.rs` are
/// different files and the SAME module.
fn module_path(src: Option<&str>) -> Option<(String, String)> {
    let src = src?;
    if !src.ends_with(".rs") {
        return None;
    }
    let i = src.find("/src/")?;
    let rel = &src[i + 5..src.len() - 3];
    let rel = rel.strip_suffix("/mod").unwrap_or(rel);
    Some((src[..i].to_string(), rel.to_string()))
}

/// Tombstone every flat record a decomposition has superseded.
///
/// # The union of the two stores is NOT the truth, and this is where that shows
///
/// `bsc graph extract` rewrites `X.rs` into `X--mod.rs` plus children and drops the flat record from
/// the COMMITTED store. The runtime store never hears about it and keeps the predecessor forever.
/// Import both and two records claim one module, which `graph-materialize` refuses outright — *"two
/// records claim module `connector` of crate `data`"* — and the whole build stops. Found by exporting
/// and running the build, not by reading the data.
///
/// MEASURED on the real stores: 152 such pairs, every one exactly one `--mod.rs` and one flat, with no
/// other shape among them. So the rule is narrow and checkable rather than a heuristic.
///
/// TOMBSTONED rather than skipped: the superseded record is imported first and then retired, so its
/// content is in the ledger and one `revert` brings it back. That is the difference between resolving
/// this and quietly dropping the loser.
pub fn supersede_decomposed(conn: &Connection, by: &str) -> Result<Vec<String>, String> {
    let mut claims: std::collections::BTreeMap<(String, String), Vec<String>> = Default::default();
    let mut st = conn
        .prepare("SELECT id, json_extract(json, '$.src') FROM records WHERE tier = 'impl'")
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, Option<String>)> = st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    for (id, src) in rows {
        if let Some(k) = module_path(src.as_deref()) {
            claims.entry(k).or_default().push(id);
        }
    }
    let mut retired = Vec::new();
    for ((krate, rel), ids) in claims {
        if ids.len() != 2 {
            continue;
        }
        let winners: Vec<&String> = ids.iter().filter(|i| i.ends_with("--mod.rs")).collect();
        if winners.len() != 1 {
            continue;
        }
        let winner = winners[0].clone();
        for id in ids.iter().filter(|i| **i != winner) {
            crate::remove(conn, id, by,
                Some(&format!("superseded by `{winner}` — both claimed module `{rel}` of `{krate}`")))?;
            retired.push(id.clone());
        }
    }
    Ok(retired)
}

/// The pre-migration history entries kept for `id`, oldest first.
pub fn legacy_history(conn: &Connection, id: &str) -> Result<Vec<Value>, String> {
    let mut st = conn
        .prepare("SELECT entry FROM legacy_history WHERE id = ?1 ORDER BY seq")
        .map_err(|e| e.to_string())?;
    let rows = st.query_map([id], |r| r.get::<_, String>(0)).map_err(|e| e.to_string())?;
    rows.map(|r| r.map_err(|e| e.to_string()).and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string())))
        .collect()
}

/// How many pre-migration history entries are preserved. `0` before the first import.
pub fn legacy_count(conn: &Connection) -> Result<i64, String> {
    conn.execute_batch(IMPORT_SCHEMA).map_err(|e| e.to_string())?;
    conn.query_row("SELECT COUNT(*) FROM legacy_history", [], |r| r.get(0)).map_err(|e| e.to_string())
}
